# 立体斜向（3D 斜向）测试地图：northup / southdown / eastup / westdown
# entry_dir="up" => enter_bit=UP(32) leave_bit=D(16)
#   入口格必须在最顶层 z=h-1，出口格必须在最底层 z=0
# 布局:
#   (1,1,1)=ENTRY --southdown--> (1,0,0)=EXIT --eastup--> (2,0,1)
#   反向: (1,0,0) -northup-> (1,1,1) ; (2,0,1) -westdown-> (1,0,0)
#   格值: (1,1,1)=UP32+SD32768=32800=0x8020
#         (1,0,0)=D16+NU1024+EU4096=5136=0x1410
#         (2,0,1)=WD131072=0x20000
[SIZE] 3,3,2
[ENTRY] 1,1,1
[EXIT] 1,0,0

[Z=0]
000 1410 000
000 000 000
000 000 000

[Z=1]
